-- Average units per order | mysql
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: [0]
-- r4 aggregate: merged; Compatible row-level input block
-- r1 project: boundary; Preserve join input scope or specialized lowering boundary
-- r0 aggregate: boundary; Preserve project input scope or specialized lowering boundary
select
  cast(
    cast(avg(cast(`r0`.`c0` as double)) as double) as double
  ) as `average_units`
from
  (
    select
      coalesce(`r1`.`c7`, cast(? as double)) as `c0`
    from
      (
        select
          `r2`.`c0` as `c0`,
          `r2`.`c1` as `c1`,
          `r2`.`c2` as `c2`,
          `r2`.`c3` as `c3`,
          `r2`.`c4` as `c4`,
          `r2`.`c5` as `c5`,
          `r6`.`c0` as `c6`,
          `r6`.`c1` as `c7`
        from
          (
            select
              `orders`.`order_id` as `c0`,
              `orders`.`order_date` as `c1`,
              `orders`.`customer_id` as `c2`,
              `orders`.`employee_id` as `c3`,
              `orders`.`shipped_date` as `c4`,
              cast(`orders`.`freight` as decimal(38, 10)) as `c5`
            from
              `orders`
          ) as `r2`
          left join (
            select
              `order_details`.`order_id` as `c0`,
              cast(
                sum(cast(`order_details`.`quantity` as double)) as double
              ) as `c1`
            from
              `order_details`
            group by
              `order_details`.`order_id`
          ) as `r6` on (`r2`.`c0` = `r6`.`c0`)
      ) as `r1`
  ) as `r0`;
